// NewBidiStreamingServer creates a typed bidirectional streaming server wrapper.
func NewBidiStreamingServer[Req, Res any](st ServerStream) BidiStreamingServer[Req, Res] {
	return &bidiStreamingServerImpl[Req, Res]{ServerStream: st}
}

// NewUnaryServer creates a typed unary server wrapper.
func NewUnaryServer[Req, Res any](st ServerStream) UnaryServer[Req, Res] {
	return &unaryServerImpl[Req, Res]{ServerStream: st}
}

