package cep

import (
	"context"

	"github.com/cloudwego/kitex/pkg/endpoint"
)

// ClientEndpoint represents a client-side RPC endpoint that can handle
// both unary and streaming calls.
type ClientEndpoint func(ctx context.Context, req, resp interface{}) error

// ClientMiddleware wraps a ClientEndpoint with additional logic.
type ClientMiddleware func(next ClientEndpoint) ClientEndpoint

// ClientMiddlewareBuilder creates a ClientMiddleware from context.
type ClientMiddlewareBuilder func(ctx context.Context) ClientMiddleware

// StreamingClientEndpoint represents a client endpoint for streaming calls.
// It provides access to the streaming context and operations.
type StreamingClientEndpoint func(ctx context.Context, stream interface{}) error

// StreamingClientMiddleware wraps a StreamingClientEndpoint with additional logic.
type StreamingClientMiddleware func(next StreamingClientEndpoint) StreamingClientEndpoint

// ChainClientMiddleware chains multiple client middlewares into one.
func ChainClientMiddleware(mws ...ClientMiddleware) ClientMiddleware {
	return func(next ClientEndpoint) ClientEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// BuildClientMiddleware builds the given middlewares into one middleware.
func BuildClientMiddleware(mws []ClientMiddleware) ClientMiddleware {
	if len(mws) == 0 {
		return DummyClientMiddleware
	}
	return func(next ClientEndpoint) ClientEndpoint {
		return mws[0](BuildClientMiddleware(mws[1:])(next))
	}
}

// DummyClientMiddleware is a no-op client middleware.
func DummyClientMiddleware(next ClientEndpoint) ClientEndpoint {
	return next
}

// DummyClientEndpoint is a no-op client endpoint.
func DummyClientEndpoint(ctx context.Context, req, resp interface{}) error {
	return nil
}

// ChainStreamingClientMiddleware chains multiple streaming client middlewares into one.
func ChainStreamingClientMiddleware(mws ...StreamingClientMiddleware) StreamingClientMiddleware {
	return func(next StreamingClientEndpoint) StreamingClientEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// AdaptToBaseEndpoint converts a ClientEndpoint to the base endpoint.Endpoint interface.
func AdaptToBaseEndpoint(ce ClientEndpoint) endpoint.Endpoint {
	return endpoint.Endpoint(ce)
}

// AdaptFromBaseEndpoint converts a base endpoint.Endpoint to ClientEndpoint.
func AdaptFromBaseEndpoint(e endpoint.Endpoint) ClientEndpoint {
	return ClientEndpoint(e)
}

// ClientEndpointContext holds client-specific context information for middleware.
type ClientEndpointContext struct {
	// TargetService is the name of the target service.
	TargetService string
	// Method is the name of the method being called.
	Method string
	// IsStreaming indicates if this is a streaming call.
	IsStreaming bool
	// StreamType indicates the type of streaming (server, client, bidi).
	StreamType string
}

type clientCtxKey int

const (
	// ClientEndpointContextKey is the key for ClientEndpointContext in context.
	ClientEndpointContextKey clientCtxKey = iota
)

// GetClientEndpointContext retrieves the ClientEndpointContext from the context.
func GetClientEndpointContext(ctx context.Context) *ClientEndpointContext {
	if v := ctx.Value(ClientEndpointContextKey); v != nil {
		if cec, ok := v.(*ClientEndpointContext); ok {
			return cec
		}
	}
	return nil
}

// WithClientEndpointContext attaches a ClientEndpointContext to the context.
func WithClientEndpointContext(ctx context.Context, cec *ClientEndpointContext) context.Context {
	return context.WithValue(ctx, ClientEndpointContextKey, cec)
}

