// Close is to release resource of ConnPool, it is executed when client is closed.
func (p *connPool) Close() error {
	p.conns.Range(func(addr, trans interface{}) bool {
		p.conns.Delete(addr)
		trans.(*transports).close()
		return true
	})
	return nil
}

// Dump returns diagnostic information about all connections in the pool.
// Returns a map where keys are remote addresses and values are slices of transport dump results.
// This method is panic-safe and will recover from any panics during dump collection.
func (p *connPool) Dump() interface{} {
	result := make(map[string]interface{})

	// Recover from any panics during dump
	defer func() {
		if r := recover(); r != nil {
			klog.Errorf("KITEX: panic during connPool.Dump(): %v", r)
		}
	}()

	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}

		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		// Collect dumps from all transports for this address
		var dumps []interface{}
		for i := 0; i < int(trans.size); i++ {
			if cliTrans := trans.cliTransports[i]; cliTrans != nil {
				// Check if transport has a Dump method via type assertion
				if dumper, ok := cliTrans.(interface{ Dump() interface{} }); ok {
					// Protect against panics from individual transport dumps
					func() {
						defer func() {
							if r := recover(); r != nil {
								klog.Errorf("KITEX: panic dumping transport for %s: %v", addr, r)
							}
						}()
						if dump := dumper.Dump(); dump != nil {
							dumps = append(dumps, dump)
						}
					}()
				}
			}
		}

		if len(dumps) > 0 {
			result[addr] = dumps
		}
		return true
	})

	return result
}

