// readAndCheckFrameHeader reads a frame header from the Framer's reader and validates it.
// If the frame size exceeds maxReadSize, returns an enhanced error with hex diagnostics
// showing the raw bytes that were read, which helps debug protocol issues.
func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Check frame size and provide detailed diagnostics if invalid
	if fh.Length > fr.maxReadSize {
		// Extract first and second 4-byte chunks for diagnostics
		var first4Bytes, second4Bytes [4]byte
		copy(first4Bytes[:], buf[:4])
		copy(second4Bytes[:], buf[4:8])
		return http2.FrameHeader{}, fmt.Errorf("%s or invalid frame (first4Bytes=%#x, second4Bytes=%#x)", 
