// StreamRecvEndpoint represents a server-side streaming receive endpoint.
type StreamRecvEndpoint func(ctx context.Context, req interface{}) (interface{}, error)

// EqualsTo returns true if both StreamRecvEndpoint instances reference the same underlying function.
func (e StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	if e == nil && e2 == nil {
		return true
	}
	if e == nil || e2 == nil {
		return false
	}
	// Compare function pointers
	return &e == &e2
}

